use std::{env,fs,io::{self,Write}};use spore_core::{creature_skin_average_v1::average,native_sse::Policy,native_x87::{Context,Precision,Rounding}};
fn main(){let a:Vec<_>=env::args().collect();assert_eq!(a.len(),2);let b=fs::read(&a[1]).unwrap();assert_eq!(b.len(),96);let mut out=Vec::new();for c in b.chunks_exact(16){let w:Vec<_>=c.chunks_exact(4).map(|v|u32::from_le_bytes(v.try_into().unwrap())).collect();let result=average([f32::from_bits(w[0]),f32::from_bits(w[1]),f32::from_bits(w[2])],w[3],Policy::Mxcsr1f80,Context{precision:Precision::Bits53,rounding:Rounding::NearestEven}).unwrap();for v in [result.reciprocal.to_bits(),result.position[0].to_bits(),result.position[1].to_bits(),result.position[2].to_bits()]{out.extend(v.to_le_bytes());}}io::stdout().write_all(&out).unwrap();}
